class HeaderComponent {
    constructor(sidebarService, layoutService, authService, router, themeService) {
        this.sidebarService = sidebarService;
        this.layoutService = layoutService;
        this.authService = authService;
        this.router = router;
        this.themeService = themeService;
        this.isDarkTheme = (localStorage.getItem('theme') || 'default') === 'dark';
    }
    ngOnInit() {
        this.userSub = this.authService.user.subscribe(user => {
            console.log("subscribed in header!");
            console.log(user);
            if (!!user) {
                this.isAuthenticated = true;
                this.userName = user.userName;
            }
            else {
                this.isAuthenticated = false;
                this.userName = "";
            }
        });
    }
    ngOnDestroy() {
        this.userSub.unsubscribe();
        this.isAuthenticated = false;
    }
    toggleSidebar() {
        this.sidebarService.toggle(true, 'menu-sidebar');
        this.layoutService.changeLayoutSize();
        return false;
    }
    navigateHome() {
    }
    login() {
        this.router.navigate(["/login"]);
    }
    toggleTheme() {
        this.isDarkTheme = !this.isDarkTheme;
        const themeName = this.isDarkTheme ? 'dark' : 'default';
        this.themeService.changeTheme(themeName);
        localStorage.setItem('theme', themeName);
    }
    logout() {
        this.authService.logout();
        localStorage.removeItem('user');
        localStorage.removeItem('token');
        this.router.navigate(["/login"]);
    }
}
