class DataBackupComponent {
    constructor(accountService) {
        this.accountService = accountService;
        this.isLoading = false;
        this.isImportLoading = false;
        this.importJson = '';
        this.importError = '';
        this.importSuccess = '';
    }
    ngOnInit() {
    }
    recoverData() {
        this.importError = '';
        this.importSuccess = '';
        let parsed;
        try {
            parsed = JSON.parse(this.importJson);
        }
        catch (e) {
            this.importError = 'Invalid JSON format. Please check your input.';
            return;
        }
        this.isImportLoading = true;
        this.accountService.uploadData(parsed).subscribe(() => {
            this.isImportLoading = false;
            this.importSuccess = 'Data recovered successfully!';
            this.importJson = '';
        }, error => {
            this.isImportLoading = false;
            this.importError = 'Recovery failed. Please try again.';
            console.log(error);
        });
    }
    downloadData() {
        this.isLoading = true;
        this.accountService.downloadData().subscribe(resData => {
            console.log(resData);
            const blob = new Blob([JSON.stringify(resData)], { type: 'application/json' });
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = 'Backup.json';
            link.click();
            this.isLoading = false;
        }, error => {
            this.isLoading = false;
            console.log(error);
        });
    }
}
