class FinancialGoalFormComponent {
    constructor(financialGoalService, resourceService, resourceGroupService) {
        this.financialGoalService = financialGoalService;
        this.resourceService = resourceService;
        this.resourceGroupService = resourceGroupService;
        this.isLoading = false;
        this.goalType = 'resource';
        this.resources = [];
        this.resourceGroups = [];
        this.selectedEntityId = '';
        this.targetValue = null;
        this.dueDate = null;
    }
    ngOnInit() {
        this.loadResources();
        this.loadResourceGroups();
    }
    loadResources() {
        this.resourceService.getResources().subscribe(resData => {
            this.resources = resData;
        });
    }
    loadResourceGroups() {
        this.resourceGroupService.getResourceGroups().subscribe(resData => {
            this.resourceGroups = resData;
        });
    }
    onGoalTypeChange() {
        this.selectedEntityId = '';
    }
    onSubmit(form) {
        if (!this.selectedEntityId || !this.targetValue || !this.dueDate) {
            return;
        }
        this.isLoading = true;
        const resourceId = this.goalType === 'resource' ? this.selectedEntityId : null;
        const resourceGroupId = this.goalType === 'resourceGroup' ? this.selectedEntityId : null;
        const dueDateStr = new Date(this.dueDate).toISOString();
        this.financialGoalService.createGoal(resourceId, resourceGroupId, this.targetValue, dueDateStr).subscribe(resData => {
            this.isLoading = false;
            this.financialGoalService.reloadTrigger.next(true);
            this.selectedEntityId = '';
            this.targetValue = null;
            this.dueDate = null;
        }, error => {
            this.isLoading = false;
            console.log(error);
        });
    }
}
